<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue';
import { Refresh, Search, MagicStick } from '@element-plus/icons-vue';
import { businessApi, type SkillSummary } from '../businessApi';
import { errorMessage, formatDate } from '../api';

const filters = reactive({ query: '', status: '', reviewStatus: '', source: '', page: 1, size: 20 });
const items = ref<SkillSummary[]>([]), total = ref(0), loading = ref(false), error = ref(''), integrationRequired = ref(false), detail = ref<SkillSummary | null>(null), detailVisible = ref(false);
let requestController: AbortController | undefined;
async function load() { requestController?.abort(); const controller = new AbortController(); requestController = controller; loading.value = true; error.value = ''; integrationRequired.value = false; try { const result = await businessApi.skills({ ...filters }, controller.signal); if (controller.signal.aborted) return; items.value = result.items; total.value = result.total; integrationRequired.value = result.integrationRequired === true; if (result.message) error.value = result.message; } catch (reason) { if (!controller.signal.aborted) error.value = errorMessage(reason); } finally { if (!controller.signal.aborted) loading.value = false; } }
function search() { filters.page = 1; void load(); } function reset() { Object.assign(filters, { query: '', status: '', reviewStatus: '', source: '', page: 1, size: 20 }); void load(); } watch(() => [filters.page, filters.size], load); onMounted(load);
function reviewType(value: string) { return value === 'APPROVED' || value === '1' ? 'success' : value === 'REJECTED' || value === '2' ? 'danger' : 'warning'; }
</script>
<template>
  <section class="page-container"><div class="page-heading"><div><h1>AI 技能商店</h1><p>迁移旧版技能商店的分类、审核、版本和下载统计，作为新项目 AI 任务的技能来源。</p></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></div>
    <el-alert v-if="integrationRequired" title="技能目录尚未接入新后台数据库" description="请先将旧版 skillStore/modelSkills 数据同步到新项目技能目录，页面不会直接读取旧后台。" type="warning" show-icon :closable="false" class="section-alert" />
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="section-alert" />
    <el-card shadow="never" class="filter-card"><el-form inline @submit.prevent="search"><el-form-item label="关键词"><el-input v-model="filters.query" clearable placeholder="技能名称、作者" :prefix-icon="Search" @keyup.enter="search" /></el-form-item><el-form-item label="来源"><el-select v-model="filters.source" clearable placeholder="全部" @change="search"><el-option label="官方" value="OFFICIAL" /><el-option label="用户上传" value="USER" /></el-select></el-form-item><el-form-item label="审核"><el-select v-model="filters.reviewStatus" clearable placeholder="全部" @change="search"><el-option label="待审核" value="PENDING" /><el-option label="已通过" value="APPROVED" /><el-option label="已拒绝" value="REJECTED" /></el-select></el-form-item><el-form-item><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form></el-card>
    <el-card shadow="never"><el-table v-loading="loading" :data="items" row-key="id" stripe empty-text="暂无技能数据"><el-table-column label="技能" min-width="235"><template #default="{ row }"><div class="primary"><el-icon><MagicStick /></el-icon> {{ row.name }}</div><div class="muted">{{ row.categoryName || '未分类' }}{{ row.platformName ? ` · ${row.platformName}` : '' }}</div></template></el-table-column><el-table-column prop="version" label="版本" width="100" /><el-table-column label="来源/作者" min-width="145"><template #default="{ row }">{{ row.source || '—' }}<div class="muted">{{ row.author || '—' }}</div></template></el-table-column><el-table-column label="审核状态" width="120"><template #default="{ row }"><el-tag size="small" :type="reviewType(row.reviewStatus)">{{ row.reviewStatus || '—' }}</el-tag></template></el-table-column><el-table-column label="启用状态" width="100"><template #default="{ row }">{{ row.status || '—' }}</template></el-table-column><el-table-column label="下载" width="90"><template #default="{ row }">{{ row.downloadCount ?? 0 }}</template></el-table-column><el-table-column label="更新时间" min-width="175"><template #default="{ row }">{{ formatDate(row.updatedAt || row.createdAt) }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="primary" @click="detail = row; detailVisible = true">查看</el-button></template></el-table-column></el-table><div class="table-footer"><span class="muted">审核通过、上下架、上传 ZIP 和租户绑定将在技能服务接入后启用。</span><el-pagination v-model:current-page="filters.page" v-model:page-size="filters.size" :total="total" :page-sizes="[20, 50, 100]" layout="total, sizes, prev, pager, next" /></div></el-card>
    <el-dialog v-model="detailVisible" title="技能详情" width="min(760px, 94vw)"><el-descriptions v-if="detail" :column="2" border><el-descriptions-item label="技能名称">{{ detail.name }}</el-descriptions-item><el-descriptions-item label="版本">{{ detail.version || '—' }}</el-descriptions-item><el-descriptions-item label="来源">{{ detail.source || '—' }}</el-descriptions-item><el-descriptions-item label="作者">{{ detail.author || '—' }}</el-descriptions-item><el-descriptions-item label="分类">{{ detail.categoryName || '—' }}</el-descriptions-item><el-descriptions-item label="平台">{{ detail.platformName || '—' }}</el-descriptions-item><el-descriptions-item label="审核状态">{{ detail.reviewStatus || '—' }}</el-descriptions-item><el-descriptions-item label="文件 MD5"><span class="mono">{{ detail.fileMd5 || '—' }}</span></el-descriptions-item><el-descriptions-item label="审核原因" :span="2">{{ detail.reviewReason || '—' }}</el-descriptions-item></el-descriptions><template #footer><el-button @click="detailVisible = false">关闭</el-button></template></el-dialog>
  </section>
</template>
<style scoped>.filter-card { margin-bottom: 16px; }.primary { color: #253451; font-weight: 600; display: flex; align-items: center; gap: 5px; }.mono { font-family: Consolas, monospace; overflow-wrap: anywhere; }</style>
